import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D9E58p8B.js";const f=JSON.parse('{"title":"Reading an interface","description":"","frontmatter":{"title":"Reading an interface"},"headers":[],"relativePath":"en/agent/lire-interface.md","filePath":"en/agent/lire-interface.md"}'),i={name:"en/agent/lire-interface.md"};function r(s,e,h,d,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="reading-an-interface" tabindex="-1">Reading an interface <a class="header-anchor" href="#reading-an-interface" aria-label="Permalink to &quot;Reading an interface&quot;">​</a></h1><p>When an application exposes its structure, the agent can read its elements instead of interpreting an image: it is more precise and more economical.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;List the buttons of the foreground window.&quot;</p><p>&quot;What is under the cursor?&quot;</p></blockquote><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><ul><li><a href="/Daimon/en/reference/touche.html#touche-tree"><code>touche_tree</code></a> returns the accessibility tree of the foreground window: each element with its role, its label and its position. The tree is bounded in depth (4 by default) and stripped of sensitive content. The agent can filter by <code>roles</code> to keep only, for example, the buttons.</li><li><a href="/Daimon/en/reference/touche.html#touche-probe"><code>touche_probe</code></a> returns the element located under a point on the screen.</li></ul><p>Both tools are <strong>read-only</strong> and are not subject to the Mains ceiling.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>A list of elements, with their positions: these are then used to act (see <a href="/Daimon/en/agent/agir.html">Acting</a>).</p><h2 id="when-the-tree-is-empty" tabindex="-1">When the tree is empty <a class="header-anchor" href="#when-the-tree-is-empty" aria-label="Permalink to &quot;When the tree is empty&quot;">​</a></h2><p>Some applications (legacy Win32 applications, custom-drawn interfaces, Electron) expose nothing. The agent then falls back on <a href="/Daimon/en/reference/vue.html#vue-find"><code>vue_find</code></a>, which locates a text on screen by OCR.</p><h2 id="if-the-call-is-refused" tabindex="-1">If the call is refused <a class="header-anchor" href="#if-the-call-is-refused" aria-label="Permalink to &quot;If the call is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>What the agent should do</th></tr></thead><tbody><tr><td><code>accessibility_permission_denied</code></td><td>The <strong>Accessibilité</strong> (Accessibility) permission is missing: <a href="/Daimon/en/guide/autorisations.html">Permissions</a></td></tr><tr><td><code>excluded</code></td><td>The target belongs to an application you have protected: the agent does not insist</td></tr><tr><td><code>snapshot_failed</code></td><td>The read failed: retry, then call <code>daimon_doctor</code></td></tr></tbody></table><p>Full detail: <a href="/Daimon/en/reference/touche.html">Touché</a>.</p>',14)])])}const p=t(i,[["render",r]]);export{f as __pageData,p as default};
